/**
 * generated by stackra gen from stackra.config.ts, expo.extend.ts when present (merged last),
 * src/config/{release,theming,i18n,identity,push,telemetry,analytics}.config.ts, runway.yaml
 * (telemetry.sentryProject, environments.dev.vars), root runway.yaml (providers.expo,
 * providers.apple, providers.sentry), .stackra/dev/ports.json, assets/public/logo.svg and
 * assets/lang/en/mobile.json — do not edit
 * Purpose: the Expo config: identifiers, owner and store ids (release), icons and splash rasterised
 *          from the logo into `.stackra/icons/` (theming), the deep-link scheme (release) and
 *          universal-link domain (env), locales (i18n), the privacy manifest of the analytics,
 *          telemetry and push drivers, the config plugins each config-bound package needs, and the
 *          fingerprint runtime policy with the update URL (env).
 * Boundary: public values only; every value here ends up in the binary. Only dev values are
 *           inlined, resolved from `from-member` / `from-port` through `.stackra/dev/ports.json`.
 *           Preview, staging and production values are build-time inputs: runway resolves every
 *           `ref:` and the per-PR origins, syncs them into the EAS environment of the profile
 *           (eas-sync.json), and EAS sets them in `process.env` before this file runs, so no
 *           unresolved placeholder reaches the binary. Every eas.json profile sets
 *           `STACKRA_ENVIRONMENT`; on an EAS worker a missing value fails the build instead of
 *           falling back to the dev values.
 * Runtime: node
 */
import type { ExpoConfig } from "expo/config";
import { env } from "@stackra/config/env";

/**
 * runway.yaml environments.dev.vars with the cross-member origins resolved from
 * .stackra/dev/ports.json.
 */
const DEV_VARS = {
  EXPO_PUBLIC_EAS_PROJECT_ID: "",
  EXPO_PUBLIC_API_ORIGIN: "http://localhost:4000",
  EXPO_PUBLIC_APP_ORIGIN: "http://localhost:5173",
  EXPO_PUBLIC_REALTIME_ORIGIN: "ws://localhost:4000/realtime",
  EXPO_PUBLIC_ZITADEL_ISSUER: "http://localhost:8080",
  EXPO_PUBLIC_ZITADEL_CLIENT_ID: "mobile-dev",
  EXPO_PUBLIC_SENTRY_DSN: "",
  EXPO_PUBLIC_PUSH_PROVIDER: "expo",
  EXPO_PUBLIC_POSTHOG_KEY: "",
} as const;

/** The runway environments (ADR 0170 d5); only `dev` is inlined above. */
const ENVIRONMENTS = ["dev", "preview", "staging", "production"] as const;

/** EAS sets `EAS_BUILD=true` on its workers, which always build an eas.json profile. */
const isEasBuild = process.env.EAS_BUILD === "true";

// A worker without STACKRA_ENVIRONMENT would build the dev values into a store binary (localhost
// universal links, no project id, updates off); fail instead.
if (isEasBuild && !process.env.STACKRA_ENVIRONMENT) {
  throw new Error(
    `STACKRA_ENVIRONMENT is not set on EAS build profile "${process.env.EAS_BUILD_PROFILE ?? "unknown"}": run \`stackra gen\` to rewrite eas.json.`,
  );
}

const environment = env.enum(ENVIRONMENTS).default("dev").parse(process.env.STACKRA_ENVIRONMENT);
const isDev = environment === "dev";
/**
 * Dev inlines the resolved values; every other environment reads what EAS set from the synced EAS
 * environment.
 */
const vars = isDev ? DEV_VARS : process.env;
/** Required outside dev: without it a release binary has no update URL. */
const easProjectId = isDev
  ? env
      .str()
      .allowEmpty()
      .parse(vars.EXPO_PUBLIC_EAS_PROJECT_ID ?? "")
  : env.str().parse(vars.EXPO_PUBLIC_EAS_PROJECT_ID);
const appHost = new URL(env.url().parse(vars.EXPO_PUBLIC_APP_ORIGIN)).host;
/**
 * Root runway providers.apple.teamId, synced into every EAS environment (eas-sync.json `build`);
 * absent on a local dev run, where Xcode signs with the developer's own team.
 */
const appleTeamId = env.str().optional().parse(process.env.STACKRA_APPLE_TEAM_ID);
/**
 * The path EAS gives the `GOOGLE_SERVICES_JSON` file variable on the worker: the FCM client config
 * Android push delivery needs (eas-sync.json `files`).
 */
const googleServicesFile = env.str().optional().parse(process.env.GOOGLE_SERVICES_JSON);

// Without the FCM config an Android release build installs but never receives a push.
if (isEasBuild && !isDev && process.env.EAS_BUILD_PLATFORM === "android" && !googleServicesFile) {
  throw new Error(
    `GOOGLE_SERVICES_JSON is not set in the "${environment}" EAS environment: Android push cannot be delivered.`,
  );
}

const config: ExpoConfig = {
  name: "Acme", // release.name
  slug: "acme-mobile", // release.slug
  owner: "acme", // root runway providers.expo.account: the EAS account that owns the project
  scheme: "acme", // release.scheme
  version: "0.1.0", // package.json
  orientation: "portrait", // release.orientation
  userInterfaceStyle: "automatic", // theming.schemes includes "system"
  icon: "./.stackra/icons/app-icon-1024.png", // rasterised from assets/public/logo.svg (theming.logo)
  // i18n.locales → CFBundleLocalizations + InfoPlist strings
  locales: { en: "./.stackra/locales/en.json", ar: "./.stackra/locales/ar.json" },
  runtimeVersion: { policy: "fingerprint" }, // release.runtimePolicy
  // env.easProjectId; a dev client from a bare clone has no update URL
  updates: easProjectId ? { url: `https://u.expo.dev/${easProjectId}` } : { enabled: false },
  // reuse a native build whose fingerprint EAS already built (release.runtimePolicy)
  buildCacheProvider: "eas",
  // the EXPO_PUBLIC_* values are inlined by Expo from process.env
  extra: { eas: { projectId: easProjectId }, stackra: { environment } },
  ios: {
    supportsTablet: true, // release.ios
    bundleIdentifier: "example.acme.mobile",
    ...(appleTeamId ? { appleTeamId } : {}),
    // theming.logo: the light, dark and tinted home-screen variants
    icon: {
      light: "./.stackra/icons/app-icon-1024.png",
      dark: "./.stackra/icons/app-icon-dark-1024.png",
      tinted: "./.stackra/icons/app-icon-tinted-1024.png",
    },
    // env.appOrigin; the member that serves it publishes apple-app-site-association
    associatedDomains: [`applinks:${appHost}`],
    config: { usesNonExemptEncryption: false },
    privacyManifests: {
      NSPrivacyTracking: false,
      // the required-reason APIs React Native and the Expo modules call
      NSPrivacyAccessedAPITypes: [
        {
          NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategoryUserDefaults",
          NSPrivacyAccessedAPITypeReasons: ["CA92.1"],
        },
        {
          NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategoryFileTimestamp",
          NSPrivacyAccessedAPITypeReasons: ["C617.1"],
        },
        {
          NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategorySystemBootTime",
          NSPrivacyAccessedAPITypeReasons: ["35F9.1"],
        },
        {
          NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategoryDiskSpace",
          NSPrivacyAccessedAPITypeReasons: ["E174.1"],
        },
      ],
      NSPrivacyCollectedDataTypes: [
        // telemetry (sentry driver): crashes and traces, tagged with the user id
        {
          NSPrivacyCollectedDataType: "NSPrivacyCollectedDataTypeCrashData",
          NSPrivacyCollectedDataTypeLinked: true,
          NSPrivacyCollectedDataTypeTracking: false,
          NSPrivacyCollectedDataTypePurposes: ["NSPrivacyCollectedDataTypePurposeAppFunctionality"],
        },
        {
          NSPrivacyCollectedDataType: "NSPrivacyCollectedDataTypePerformanceData",
          NSPrivacyCollectedDataTypeLinked: true,
          NSPrivacyCollectedDataTypeTracking: false,
          NSPrivacyCollectedDataTypePurposes: ["NSPrivacyCollectedDataTypePurposeAppFunctionality"],
        },
        // analytics (posthog driver): screen views and events, only after consent
        {
          NSPrivacyCollectedDataType: "NSPrivacyCollectedDataTypeProductInteraction",
          NSPrivacyCollectedDataTypeLinked: true,
          NSPrivacyCollectedDataTypeTracking: false,
          NSPrivacyCollectedDataTypePurposes: ["NSPrivacyCollectedDataTypePurposeAnalytics"],
        },
        // telemetry and analytics: the user id, never an email or a name
        {
          NSPrivacyCollectedDataType: "NSPrivacyCollectedDataTypeUserID",
          NSPrivacyCollectedDataTypeLinked: true,
          NSPrivacyCollectedDataTypeTracking: false,
          NSPrivacyCollectedDataTypePurposes: [
            "NSPrivacyCollectedDataTypePurposeAppFunctionality",
            "NSPrivacyCollectedDataTypePurposeAnalytics",
          ],
        },
        // push (expo driver): the device's push token, registered with the devices module
        {
          NSPrivacyCollectedDataType: "NSPrivacyCollectedDataTypeDeviceID",
          NSPrivacyCollectedDataTypeLinked: true,
          NSPrivacyCollectedDataTypeTracking: false,
          NSPrivacyCollectedDataTypePurposes: ["NSPrivacyCollectedDataTypePurposeAppFunctionality"],
        },
      ],
    },
  },
  android: {
    package: "example.acme.mobile", // release.android
    ...(googleServicesFile ? { googleServicesFile } : {}),
    predictiveBackGestureEnabled: false,
    // theming.themeColor.light; the monochrome layer is Android 13's themed icon
    adaptiveIcon: {
      foregroundImage: "./.stackra/icons/adaptive-foreground-1024.png",
      monochromeImage: "./.stackra/icons/adaptive-monochrome-1024.png",
      backgroundColor: "#f7f7f5",
    },
    // permissions a dependency adds that no route's capability needs
    blockedPermissions: [
      "android.permission.RECORD_AUDIO",
      "android.permission.READ_EXTERNAL_STORAGE",
      "android.permission.WRITE_EXTERNAL_STORAGE",
    ],
    // env.appOrigin; the member that serves it publishes assetlinks.json
    intentFilters: [
      {
        action: "VIEW",
        autoVerify: true,
        data: [{ scheme: "https", host: appHost, pathPrefix: "/m" }],
        category: ["BROWSABLE", "DEFAULT"],
      },
    ],
  },
  plugins: [
    "react-native-bottom-tabs", // routes/tabs.layout.ts kind NativeTabs
    "expo-secure-store", // storage drivers (session, secrets)
    "expo-sqlite", // storage drivers (cache, outbox)
    "expo-web-browser", // identity.flow pkce
    [
      "expo-camera",
      {
        cameraPermission: "Acme scans product barcodes to add them to an order.",
        microphonePermission: false,
        recordAudioAndroid: false,
      },
      // routes/scan.route.ts capability scanner (barcodes only, never audio); the string is
      // assets/lang/en/mobile.json permissions.camera
    ],
    // push.config.ts; theming.themeColor.dark
    ["expo-notifications", { icon: "./.stackra/icons/notification-96.png", color: "#1c1e22" }],
    "expo-updates", // configured by `updates` and `runtimeVersion` above
    // telemetry.errors.enabled; org from root providers.sentry.org, project from runway.yaml
    // telemetry.sentryProject; DSN is a var; the upload token is a CI secret
    ["@sentry/react-native/expo", { organization: "acme", project: "acme-mobile" }],
    [
      "expo-splash-screen",
      {
        image: "./.stackra/icons/splash-256.png",
        imageWidth: 96,
        backgroundColor: "#f7f7f5",
        dark: { image: "./.stackra/icons/splash-dark-256.png", backgroundColor: "#1c1e22" },
      },
    ], // theming.splash
  ],
};

export default config;
